SELECT location, CASE WHEN budget >= 3952000 THEN 'high' WHEN budget >= 611000 THEN 'mid' ELSE 'low' END AS budget_bucket, ROUND((100 * SUM(CASE WHEN dept_name = 'Marketing' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_marketing, ROUND(STDDEV(budget), 2) AS stddev_budget, ROUND(AVG(budget), 2) AS avg_budget FROM departments WHERE budget <= 2520000 GROUP BY CUBE(location, CASE WHEN budget >= 3952000 THEN 'high' WHEN budget >= 611000 THEN 'mid' ELSE 'low' END)
